import asyncio,json,os
from pathlib import Path
from playwright.async_api import async_playwright
ROOT=Path(__file__).resolve().parents[4]
async def main():
 env={**os.environ,'YOURWIKI_BROWSER_PORT':'39088','YOURWIKI_BROWSER_CONTROL':'1'}
 server=await asyncio.create_subprocess_exec('node','apps/server/test/support/pdf-browser-server.ts',cwd=ROOT,env=env,stdin=asyncio.subprocess.PIPE,stdout=asyncio.subprocess.PIPE,stderr=asyncio.subprocess.PIPE)
 try:
  line=await asyncio.wait_for(server.stdout.readline(),20);assert b'Synthetic PDF' in line,(line,await server.stderr.read())
  async with async_playwright() as p:
   browser=await p.chromium.launch(executable_path=os.environ['PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH'],headless=True,args=['--no-sandbox']);context=await browser.new_context(locale='ru-RU',viewport={'width':393,'height':852});page=await context.new_page();page.set_default_timeout(9000);errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.on('console',lambda m:errors.append(m.text) if m.type=='error' and 'Content Security Policy' in m.text else None)
   await page.goto('http://127.0.0.1:39088/');await page.locator('input[name=username]').fill('qa');await page.locator('input[name=password]').fill('yourwiki-qa');await page.get_by_role('button',name='Войти',exact=True).click();await page.get_by_role('link',name='Аккаунт',exact=True).click();animation=page.get_by_role('checkbox',name='Включить анимации',exact=True);await animation.wait_for();assert not await animation.is_checked();await animation.check();await page.get_by_role('button',name='Сохранить',exact=True).click();await page.get_by_text('Настройки сохранены.',exact=True).wait_for();await page.reload();await animation.wait_for();assert await animation.is_checked()
   await page.get_by_role('link',name='Dashboard',exact=True).click();await page.get_by_role('button',name='Изменить страницу',exact=True).click();await page.get_by_role('button',name='Добавить блок',exact=True).click();await page.get_by_label('Текст',exact=True).fill('P0 dashboard content');await page.get_by_role('button',name='Сохранить',exact=True).click();await page.get_by_text('P0 dashboard content',exact=True).wait_for();await page.reload();await page.get_by_text('P0 dashboard content',exact=True).wait_for()
   await page.get_by_role('link',name='Настройки',exact=True).click();form=page.locator('fieldset').filter(has=page.locator('legend',has_text='Новый пользователь'));await form.locator('input[name=username]').fill('p0-member');await form.locator('input[name=displayName]').fill('P0 member');await form.locator('input[name=password]').fill('P0-password-123');await form.get_by_role('button',name='Создать',exact=True).click();row=page.locator('.admin-list li').filter(has=page.get_by_text('P0 member',exact=True));await row.wait_for();page.once('dialog',lambda d:d.accept());await row.get_by_role('button',name='В корзину',exact=True).click();await row.wait_for(state='detached');await page.get_by_role('button',name='Корзина',exact=True).click();entry=page.locator('.admin-list li').filter(has=page.get_by_text('p0-member',exact=True));await entry.wait_for();await entry.get_by_role('button',name='Восстановить',exact=True).click();await entry.wait_for(state='detached');await page.get_by_role('button',name='Пользователи',exact=True).click();await page.get_by_text('P0 member',exact=True).wait_for()
   geometry=await page.evaluate('({width:innerWidth,scroll:document.documentElement.scrollWidth})');assert geometry['width']==geometry['scroll'],geometry;assert not errors,errors
   await page.screenshot(path=str(ROOT/'output/playwright/admin-profile-dashboard-mobile.png'),full_page=True);print(json.dumps({'accountPreferences':'persisted','dashboard':'persisted','users':'create-trash-restore','viewport':393,'errors':errors}));await browser.close()
 finally:
  server.terminate();await asyncio.wait_for(server.wait(),15)
asyncio.run(main())
